    21→
    22→const getTextContent = (event: EventTimelineItem): string => {
    23→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    24→    const kind = event.content.inner.content.kind;
    25→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    26→      const msgType = kind.inner.content.msgType;
    27→      if (msgType?.tag === MessageType_Tags.Text) {
    28→        return kind.inner.content.body;
    29→      }
    30→    }
    31→  }
    32→  return "";
    33→};
    34→
    35→export const TextMessage: FC<Props> = ({ event, isPreviousSameSender }) => {
    36→  const [messageWidth, setMessageWidth] = useState(40);
    37→  const isUser = event.isOwn;
    38→  const sender = event.senderProfile;
    39→  const senderId = event.sender;
    40→  const [seenBy, setSeenBy] = useState<UserProfile[]>([]);
    41→  const content = getTextContent(event);
    42→
    43→  useEffect(() => {
    44→    MatrixService.getReadReceipts(event)
    45→      .then((users) => {
    46→        setSeenBy(users);
    47→      })
    48→      .catch((error) => {
    49→        console.error("Failed to get read receipt users:", error);
    50→        setSeenBy([]);
    51→      });
    52→  }, [event]);
    53→
    54→  return (
    55→    <Block
    56→      align={isUser ? "flex-end" : "flex-start"}
    57→      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    58→    >
    59→      <MessageSender
    60→        sender={sender}
    61→        senderId={senderId}
    62→        isUser={isUser}
    63→        isPreviousSameSender={isPreviousSameSender}
    64→      />
    65→      <Block
    66→        paddings={12}
    67→        background={isUser ? Colors.primary : Colors.message}
    68→        border={{
    69→          borderRadius: 24,
    70→        }}
    71→        flexDirection={isUser ? "row-reverse" : "row"}
    72→        gap={{
    73→          row: 4,
    74→          col: 16,
    75→        }}
    76→        align="center"
    77→        flex={{ flexWrap: "wrap" }}
    78→        onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
    79→      >
    80→        <Text size={TextSize.small} color="white" font="Gridlite-PEVFTRIAL">
    81→          {content}
    82→        </Text>
    83→        <Text size={TextSize.tiny} color={Colors.white50}>
    84→          {format(Number(event.timestamp), "HH:mm")}
    85→        </Text>
    86→        {isPreviousSameSender && (
    87→          <Block
    88→            absolute
    89→            offsets={
    90→              isUser
    91→                ? {
    92→                    right: 6,
    93→                    bottom: 2,
    94→                  }
    95→                : {
    96→                    left: 6,
    97→                    bottom: 2,
    98→                  }
    99→            }
   100→          >
   101→            <Image
   102→              source={
   103→                isUser
   104→                  ? require("assets/icons/polygon.png")
   105→                  : require("assets/icons/guest-polygon.png")
   106→              }
   107→              width={7}
   108→              height={6}
   109→              style={styles.polygon}
   110→            />
   111→          </Block>
   112→        )}
   113→      </Block>
   114→      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
   115→    </Block>
   116→  );
   117→};
   118→
   119→const styles = StyleSheet.create({
   120→  polygon: {
   121→    width: 7,
   122→    height: 6,
   123→  },
   124→});
