    28→const getImageContent = (
    29→  event: EventTimelineItem,
    30→): ImageMessageContent | null => {
    31→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    32→    const kind = event.content.inner.content.kind;
    33→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    34→      const msgType = kind.inner.content.msgType;
