    43→export const ImageMessage: FC<Props> = ({ event, isPreviousSameSender }) => {
    44→  const content = getImageContent(event);
    45→  const [messageWidth, setMessageWidth] = useState(40);
    46→  const originalWidth = Number(content?.info?.thumbnailInfo?.width) || 0;
    47→  const originalHeight = Number(content?.info?.thumbnailInfo?.height) || 0;
    48→  const scaleRatio = Math.min(
    49→    MAX_DIMENSION / originalWidth,
    50→    MAX_DIMENSION / originalHeight,
    51→    1,
    52→  );
    53→  const targetWidth = Math.round(originalWidth * scaleRatio);
    54→  const targetHeight = Math.round(originalHeight * scaleRatio);
    55→  const [uri, setUri] = useState<string | null>(null);
    56→  const [isLoading, setIsLoading] = useState(true);
    57→  const isUser = event.isOwn;
