    91→        setIsLoading(false);
    92→      }
    93→    };
    94→
    95→    fetch();
    96→  }, [content]);
    97→
    98→  if (!content) return null;
    99→
   100→  return (
   101→    <Block
   102→      align={isUser ? "flex-end" : "flex-start"}
