   131→              align="center"
   132→              justify="center"
   133→            >
   134→              <Loading isFullScreen={false} />
   135→            </Block>
   136→          ) : uri ? (
   137→            <Image
   138→              source={{ uri }}
   139→              width={targetWidth}
   140→              height={targetHeight}
   141→              resizeMode="contain"
   142→            />
   143→          ) : null}
   144→        </Block>
   145→      </Button.Wrapper>
   146→      <Block
   147→        align={isUser ? "flex-end" : "flex-start"}
   148→        margins={{ marginTop: 12 }}
   149→      >
   150→        {caption ? (
   151→          <Block
   152→            paddings={12}
   153→            background={isUser ? Colors.primary : Colors.message}
   154→            border={{
   155→              borderRadius: 24,
   156→            }}
   157→            flexDirection={isUser ? "row-reverse" : "row"}
   158→            gap={{
   159→              row: 4,
   160→              col: 16,
   161→            }}
   162→            align="center"
   163→            flex={{ flexWrap: "wrap" }}
   164→            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
   165→          >
   166→            <Text size={TextSize.small} color="white" font="Gridlite-PEVFTRIAL">
   167→              {caption}
   168→            </Text>
   169→            <Text size={TextSize.tiny} color={Colors.white50}>
