     1→import { Block, Text } from "@prototyp/skeletor";
     2→import {
     3→  type AudioMessageContent,
     4→  type EventTimelineItem,
     5→  MessageType_Tags,
     6→  MsgLikeKind_Tags,
     7→  TimelineItemContent_Tags,
     8→  type UserProfile,
     9→} from "@unomed/react-native-matrix-sdk";
    10→import { format } from "date-fns";
    11→import { MatrixService } from "modules/matrix-client/services";
    12→import { useAudioPlayback } from "modules/recorder-player/hooks";
    13→import type { FC } from "react";
    14→import { useEffect, useState } from "react";
    15→import { Image, StyleSheet } from "react-native";
    16→import Toast from "react-native-toast-message";
    17→import { Button, Loading, SeenBy } from "shared/components";
    18→import { Colors, TextSize } from "shared/styles";
    19→import { MessageSender } from "../message-sender";
    20→
    21→interface Props {
    22→  event: EventTimelineItem;
    23→  isPreviousSameSender: boolean;
    24→}
    25→
    26→function formatDuration(milliseconds: number) {
    27→  const totalSeconds = Math.max(0, Math.ceil(milliseconds / 1000));
    28→  const minutes = Math.floor(totalSeconds / 60);
    29→  const seconds = totalSeconds % 60;
    30→  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
    31→}
    32→
    33→const getAudioContent = (
    34→  event: EventTimelineItem,
    35→): AudioMessageContent | null => {
    36→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    37→    const kind = event.content.inner.content.kind;
    38→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    39→      const msgType = kind.inner.content.msgType;
    40→      if (msgType?.tag === MessageType_Tags.Audio) {
    41→        return msgType.inner.content;
    42→      }
    43→    }
    44→  }
    45→  return null;
    46→};
    47→
    48→export const VoiceMessage: FC<Props> = ({ event, isPreviousSameSender }) => {
    49→  const content = getAudioContent(event);
    50→  const eventId =
    51→    "inner" in event.eventOrTransactionId
    52→      ? "eventId" in event.eventOrTransactionId.inner
    53→        ? event.eventOrTransactionId.inner.eventId
    54→        : event.eventOrTransactionId.inner.transactionId
    55→      : String(event.timestamp);
    56→  const [messageWidth, setMessageWidth] = useState(40);
    57→  const [isLoading, setIsLoading] = useState(false);
    58→  const isUser = event.isOwn;
    59→  const sender = event.senderProfile;
    60→  const senderId = event.sender;
    61→  const duration = content?.info?.duration ?? 0;
    62→  const [seenBy, setSeenBy] = useState<UserProfile[]>([]);
    63→  const { isPlaying, currentMs, play, pause, resume } =
    64→    useAudioPlayback(eventId);
    65→
    66→  useEffect(() => {
    67→    MatrixService.getReadReceipts(event)
    68→      .then((users) => {
    69→        setSeenBy(users);
    70→      })
    71→      .catch((error) => {
    72→        console.error("Failed to get read receipt users:", error);
    73→        setSeenBy([]);
    74→      });
    75→  }, [event]);
    76→
    77→  const onTogglePlay = async () => {
    78→    //For these types of voice messages, we need to convert them to m4a with ffmpeg
    79→    if (["audio/ogg", "audio/opus"].includes(content?.info?.mimetype ?? "")) {
    80→      Toast.show({
    81→        type: "error",
    82→        text1: "This voice message is not supported on this device.",
    83→      });
    84→      return;
    85→    }
    86→
    87→    try {
    88→      setIsLoading(true);
    89→
    90→      if (isPlaying) {
    91→        await pause();
    92→        return;
    93→      }
    94→
    95→      // If paused mid-track and not at the end, resume instead of restarting
    96→      if (currentMs > 0 && currentMs < duration) {
    97→        await resume();
    98→        return;
    99→      }
   100→
   101→      // Re-fetch the playback URL to ensure it's valid (temp files may be cleaned up)
   102→      if (!content?.source || !MatrixService.instance) {
   103→        Toast.show({
   104→          type: "error",
   105→          text1: "Failed to fetch voice message.",
   106→        });
   107→        return;
   108→      }
   109→
   110→      const mediaHandle = await MatrixService.instance.getMediaFile(
   111→        content?.source,
   112→        `voice-${eventId}.${content.info?.mimetype?.split("/")[1] ?? "m4a"}`,
   113→        content.info?.mimetype || "audio/m4a",
   114→        true, // useCache
   115→        undefined,
   116→      );
   117→
   118→      const filePath = mediaHandle.path();
   119→      const freshUrl = filePath.startsWith("file://")
   120→        ? filePath
   121→        : `file://${filePath}`;
   122→
   123→      await play(freshUrl, duration);
   124→    } catch (e) {
   125→      Toast.show({
   126→        type: "error",
   127→        text1: "Failed to play voice message.",
   128→      });
   129→      console.log(e);
   130→    } finally {
   131→      setIsLoading(false);
   132→    }
   133→  };
   134→
   135→  if (!content) return null;
   136→
   137→  return (
   138→    <Block
   139→      align={isUser ? "flex-end" : "flex-start"}
   140→      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
   141→    >
   142→      <MessageSender
   143→        sender={sender}
   144→        isUser={isUser}
   145→        senderId={senderId}
   146→        isPreviousSameSender={isPreviousSameSender}
   147→      />
   148→      <Block
   149→        paddings={12}
   150→        background={isUser ? Colors.primary : Colors.message}
   151→        border={{
   152→          borderRadius: 24,
   153→        }}
   154→        flexDirection={isUser ? "row-reverse" : "row"}
   155→        gap={{
   156→          row: 8,
   157→          col: 16,
   158→        }}
   159→        align="center"
   160→        onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
   161→      >
   162→        <Button.Wrapper
   163→          disabled={isLoading}
   164→          onPress={onTogglePlay}
   165→          style={styles.playButton}
   166→        >
   167→          {isLoading ? (
   168→            <Loading isFullScreen={false} />
   169→          ) : (
   170→            <Image
   171→              source={
   172→                isPlaying
   173→                  ? require("assets/icons/pause-big.png")
   174→                  : require("assets/icons/play.png")
   175→              }
   176→              tintColor={Colors.white}
   177→            />
   178→          )}
   179→        </Button.Wrapper>
   180→        <Block flex={1} gap={4}>
   181→          <Block
   182→            height={4}
   183→            background={Colors.white20}
   184→            border={{ borderRadius: 2 }}
   185→          >
   186→            <Block
   187→              height={4}
   188→              width={`${Math.min(100, Math.round((currentMs / duration) * 100))}%`}
   189→              background={Colors.white50}
   190→              border={{ borderRadius: 2 }}
   191→            />
   192→          </Block>
   193→          <Block flexDirection="row" justify="space-between">
   194→            <Text size={TextSize.tiny} color={Colors.white80}>
   195→              {formatDuration(currentMs)}
   196→            </Text>
   197→            <Text size={TextSize.tiny} color={Colors.white50}>
   198→              {formatDuration(duration)}
   199→            </Text>
   200→          </Block>
   201→        </Block>
   202→        <Text size={TextSize.tiny} color={Colors.white50}>
   203→          {format(Number(event.timestamp), "HH:mm")}
   204→        </Text>
   205→      </Block>
   206→      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
   207→    </Block>
   208→  );
   209→};
   210→
   211→const styles = StyleSheet.create({
   212→  playButton: {
   213→    width: 40,
   214→    height: 40,
   215→    alignItems: "center",
   216→    justifyContent: "center",
   217→    backgroundColor: Colors.white20,
   218→    borderRadius: 20,
   219→  },
   220→});
