     6→import { Gesture, GestureDetector } from "react-native-gesture-handler";
     7→import Animated, {
     8→  runOnJS,
     9→  useAnimatedStyle,
    10→  useSharedValue,
    11→  withSpring,
    12→} from "react-native-reanimated";
    13→import { Colors } from "shared/styles";
    14→import { Button } from "../button";
    15→
    16→interface ImageViewerModalProps {
    17→  visible: boolean;
    18→  imageUri: string;
    19→  onClose: () => void;
    20→  images?: string[];
    21→  initialIndex?: number;
    22→}
    23→
    24→const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");
    25→
    26→export const ImageViewerModal: FC<ImageViewerModalProps> = ({
    27→  visible,
    28→  imageUri,
    29→  images = [imageUri],
    30→  initialIndex = 0,
    31→  onClose,
    32→}) => {
    33→  const [currentIndex, setCurrentIndex] = useState(initialIndex);
    34→  const currentImage = images[currentIndex] || imageUri;
    35→  const translateX = useSharedValue(0);
    36→
    37→  useEffect(() => {
    38→    if (visible) setCurrentIndex(initialIndex);
    39→  }, [visible, initialIndex]);
    40→
    41→  const goToNextImage = () => {
    42→    if (currentIndex === images.length - 1) return;
    43→    setCurrentIndex((prev) => prev + 1);
    44→  };
    45→
    46→  const goToPreviousImage = () => {
    47→    if (currentIndex === 0) return;
    48→    setCurrentIndex((prev) => prev - 1);
    49→  };
    50→
    51→  const panGesture = Gesture.Pan()
    52→    .onUpdate((event) => {
    53→      translateX.value = event.translationX;
    54→    })
    55→    .onEnd((event) => {
    56→      const swipeThreshold = SCREEN_WIDTH * 0.25;
    57→      const velocityThreshold = 500;
    58→
    59→      if (
    60→        event.translationX < -swipeThreshold ||
    61→        event.velocityX < -velocityThreshold
    62→      ) {
    63→        runOnJS(goToNextImage)();
    64→      } else if (
    65→        event.translationX > swipeThreshold ||
    66→        event.velocityX > velocityThreshold
    67→      ) {
    68→        runOnJS(goToPreviousImage)();
    69→      }
    70→
    71→      translateX.value = withSpring(0);
    72→    });
    73→
    74→  const animatedStyle = useAnimatedStyle(() => ({
    75→    transform: [{ translateX: translateX.value }],
    76→  }));
    77→
    78→  return (
    79→    <Modal
    80→      visible={visible}
    81→      animationType="fade"
    82→      statusBarTranslucent
    83→      transparent
    84→      onRequestClose={onClose}
    85→    >
    86→      <Block background={Colors.black} flex={1} justify="center" align="center">
    87→        <Block
    88→          absolute
    89→          offsets={{ top: 60, right: 20 }}
    90→          zIndex={10}
    91→          background={Colors.white20}
    92→          border={{ borderRadius: 999 }}
    93→          paddings={[12, 12]}
    94→        >
    95→          <Button.Wrapper onPress={onClose}>
    96→            <Image source={require("assets/icons/close.png")} />
    97→          </Button.Wrapper>
    98→        </Block>
    99→
   100→        {images.length > 1 ? (
   101→          <GestureDetector gesture={panGesture}>
   102→            <Animated.View style={[styles.container, animatedStyle]}>
   103→              <ImageZoom
   104→                uri={currentImage}
   105→                minScale={1}
   106→                maxScale={5}
   107→                maxPanPointers={2}
   108→                isPanEnabled
   109→                isPinchEnabled
   110→                isDoubleTapEnabled
   111→                style={styles.image}
   112→                resizeMode="contain"
   113→              />
   114→            </Animated.View>
   115→          </GestureDetector>
   116→        ) : (
   117→          <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
   118→            <ImageZoom
   119→              uri={currentImage}
   120→              minScale={1}
   121→              maxScale={5}
   122→              maxPanPointers={2}
   123→              isPanEnabled
   124→              isPinchEnabled
   125→              isDoubleTapEnabled
   126→              style={styles.image}
   127→              resizeMode="contain"
   128→            />
   129→          </Block>
